# Function to count occurrences of the most common element
def count_most_common(n, k, elements):
    counts = {}
    for elem in elements:
        if elem in counts:
            counts[elem] += 1
        else:
            counts[elem] = 1
    max_count = max(counts.values())
    if k == max_count:
        return True
    for elem in counts:
        if counts[elem] == max_count:
            for i in range(len(elements)):
                if elements[i] == elem:
                    return True
            return False
    return False

# Main function to solve the problem
def solve():
    n, k = get_n_and_k()
    elements = list(map(int, input().split()))
    if count_most_common(n, k, elements):
        print("YES")
    else:
