def solve(i: int, code: List[str]) -> int:
    N, total_operations = len(code), 0

    # Calculate number of operations to turn a single bulb on/off
    def on_off(bulb: int) -> None:
        if bulb < 1 or bulb > 4:
            return

        # Get colors of bulbs before the operation
        prev_colors = list(code[:bulb])

        # Get colors of bulbs after the operation
        next_colors = list(code[bulb + 1:])

        # Sort bulbs with the same color
        if prev_colors == next_colors:
            return

        prev_colors.remove(prev_colors[0])
        next_colors.remove(next_colors[0])

        # Check if it's possible to turn all bulbs on
        for i, color in enumerate(prev_colors):
            if color!= next_colors[i]:
                return -1  # Impossible to turn all bulbs on

        # Try two solutions for the rest of the bulbs
        for j in range(bulb + 1, len(code)):
            if code[j] == prev_colors[j]:
                on_off(j)
                break

    # Count number of operations for each color
    for color in range(1, 5):
        total_operations += on_off(color)

    return total_operations if total_operations!= -1 else -1

