import os
import sys

def solve(grid):
    rows = len(grid)
    cols = len(grid[0])
    directions = [[1, 0], [0, 1], [-1, 0], [0, -1]]
    dist = [[float('inf')] * cols for _ in range(rows)]

    # Initialize with 0s and store minimum cost to fill in the grid
    for i in range(rows):
        dist[i][0] = 0
        for j in range(cols):
            dist[i][j] = 0 if grid[i][j] == 0 else float('inf')

    # Compute the shortest cost to fill in the grid
    for k in range(rows):
        for i in range(cols):
            for d in directions:
                ni, nj = i + d[0], j + d[1]
                if 0 <= ni < rows and 0 <= nj < cols:
                    dist[k][nj] = min(dist[k][nj], dist[k][i] + 1 + dist[i][j])

    # Find the minimum cost to fill the grid with zeros
    ans = float('inf')
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0:
                ans = min(ans, dist[i][j])

    return ans

